import { useSuspenseQuery } from '@tanstack/react-query';
import { createFileRoute, Navigate } from '@tanstack/react-router';
import { useCallback } from 'react';

import { useModal } from '@/hooks/useModal';
import { getAccountMeQueryOptions } from '@/query/options/account';
import { AllCreditsExhaustedModal } from '@/routes/_authenticated/credit-plan/-components/InsufficientCreditModal/AllCreditsExhaustedModal';
import { DailyLimitExceededModal } from '@/routes/_authenticated/credit-plan/-components/InsufficientCreditModal/DailyLimitExceededModal';
import { FreeTrialExhaustedModal } from '@/routes/_authenticated/credit-plan/-components/InsufficientCreditModal/FreeTrialExhaustedModal';
import { Step5Settings } from '@/routes/_authenticated/start/-components/steps/Step5Settings';
import { isFreeDraftTemplate } from '@/routes/_authenticated/start/-components/steps/draftTemplateProfile';
import { useStartFlow } from '@/routes/_authenticated/start/-startFlow.context';

export const Route = createFileRoute('/_authenticated/start/settings/')({
  component: RouteComponent
});

function RouteComponent() {
  const modal = useModal();
  const { data: me } = useSuspenseQuery(getAccountMeQueryOptions());
  const {
    selectedDraftTemplate,
    hasGeneratedSuggestions,
    templateName,
    theme,
    setTheme,
    goToVisualSuggestions,
    startGenerate
  } = useStartFlow();

  const handleSubmit = useCallback(() => {
    if (isFreeDraftTemplate(selectedDraftTemplate)) {
      startGenerate();
      return;
    }

    if (!me.canCreateDraftExport) {
      modal.openModal(({ isOpen, onClose }) => (
        <FreeTrialExhaustedModal isOpen={isOpen} onClose={onClose} />
      ));
      return;
    }

    if (me.hasProAccess && me.freeCredit < me.productExportCredit) {
      if (me.paidCredit <= 0) {
        modal.openModal(({ isOpen, onClose }) => (
          <AllCreditsExhaustedModal isOpen={isOpen} onClose={onClose} />
        ));
        return;
      }

      modal.openModal(({ isOpen, onClose }) => (
        <DailyLimitExceededModal
          isOpen={isOpen}
          onClose={onClose}
          paidCredit={me.paidCredit}
          onConfirm={me.paidCredit > 0 ? () => startGenerate() : undefined}
        />
      ));
      return;
    }

    startGenerate();
  }, [me, modal, selectedDraftTemplate, startGenerate]);

  if (!selectedDraftTemplate) {
    return <Navigate to="/start/template" replace />;
  }

  if (!hasGeneratedSuggestions) {
    return <Navigate to="/start/upload" replace />;
  }

  return (
    <Step5Settings
      templateName={templateName}
      initialTheme={theme}
      onThemeChange={setTheme}
      onBack={goToVisualSuggestions}
      onSubmit={handleSubmit}
    />
  );
}
