import { useCallback, useEffect, useState } from 'react';
import {
  Button,
  Dialog,
  Flex,
  Menu,
  MenuContent,
  MenuItem,
  MenuTrigger,
} from '@bichon/ds';
import type {
  CharacterStyle,
  ParagraphStyle,
  Theme
} from '@docshunt/docs-editor-wasm';
import { ChevronDown, Info, TriangleAlert } from 'lucide-react';
import {
  DEFAULT_THEME,
  FONT_SIZES,
  LINE_SPACINGS,
  MARK_OPTIONS,
  PARAGRAPH_SPACINGS,
  PREVIEW_TEXTS,
  STYLE_DISPLAY_NAMES
} from '@/components/DocsThemeDialog/DocsThemeDialog.constant';
import { useLocalFonts } from '@/hooks/useLocalFonts';
import {
  buildPreviewStyle,
  getCharacterValue,
  getParagraphValue
} from '@/components/DocsThemeDialog/DocsThemeDialog.helpers';
import type { LocalEdits } from '@/components/DocsThemeDialog/DocsThemeDialog.type';
import { useModal } from '@/hooks/useModal';
import { StyledFunnelContentWrapper } from '@/routes/_authenticated/f/-route.style';
import {
  StyledStepHeader,
  StyledTemplateName,
  StyledStepSubtitle,
  StyledInfoBanner,
  StyledSettingsFooter,
  StyledStyleCard,
  StyledCardTitle,
  StyledCardDescription,
  StyledFieldsWrapper,
  StyledFieldGroup,
  StyledFieldLabel,
  StyledMenuTriggerBox,
  StyledAttrGroup,
  StyledAttrButton,
  StyledPreviewBox,
  StyledPreviewLine,
  StyledPreviewNotice,
  StyledContentRow,
  StyledStyleList,
  StyledStylePill,
  StyledPropertiesPanel,
  StyledFieldRow,
  StyledHorizontalDivider
} from '@/routes/_authenticated/f/settings/-settings.style';

interface Step5Props {
  templateName: string;
  initialTheme?: Theme;
  onThemeChange: (theme: Theme | undefined) => void;
  onBack: () => void;
  onSubmit: () => void;
}

const REMOVE_FIELD = Symbol('REMOVE_FIELD');

export function Step5Settings({
  templateName,
  initialTheme,
  onThemeChange,
  onBack,
  onSubmit
}: Step5Props) {
  const modal = useModal();
  const [theme, setTheme] = useState<Theme>(initialTheme ?? DEFAULT_THEME);
  const { fallbackFonts, localFonts, requestFonts } = useLocalFonts();

  const { style, character, paragraph } = theme;

  const [selectedKey, setSelectedKey] = useState(
    Object.keys(style)[0] ?? 'l1'
  );
  const [edits, setEdits] = useState<LocalEdits>({});

  useEffect(() => {
    requestFonts();
  }, [requestFonts]);

  const updateCharacter = useCallback(
    (field: keyof CharacterStyle, value: unknown) => {
      setEdits((prev) => ({
        ...prev,
        [selectedKey]: {
          character: { ...prev[selectedKey]?.character, [field]: value },
          paragraph: prev[selectedKey]?.paragraph ?? {}
        }
      }));
    },
    [selectedKey]
  );

  const updateParagraph = useCallback(
    (field: keyof ParagraphStyle, value: unknown) => {
      setEdits((prev) => ({
        ...prev,
        [selectedKey]: {
          character: prev[selectedKey]?.character ?? {},
          paragraph: {
            ...prev[selectedKey]?.paragraph,
            [field]: value === null ? REMOVE_FIELD : value
          }
        }
      }));
    },
    [selectedKey]
  );

  const toggleCharBool = useCallback(
    (field: 'bold' | 'italic' | 'underline' | 'strike') => {
      const entry = style[selectedKey];
      if (!entry) return;
      const current = getCharacterValue(
        edits,
        selectedKey,
        character[entry.character_style ?? ''],
        field
      ) as boolean | undefined;
      updateCharacter(field, !current);
    },
    [edits, selectedKey, character, style, updateCharacter]
  );

  const handleReset = useCallback(() => {
    modal.openModal(({ isOpen, onClose }) => (
      <Dialog isOpen={isOpen} onClose={onClose}>
        <Dialog.Content>
          <Flex direction="column" alignItems="center" gap={16} style={{ padding: '8px 0' }}>
            <div
              style={{
                width: 56,
                height: 56,
                borderRadius: '50%',
                backgroundColor: '#FFECEE',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
            >
              <TriangleAlert size={28} color="#F04452" />
            </div>
            <Flex direction="column" alignItems="center" gap={8}>
              <span style={{ fontSize: 18, fontWeight: 600, color: '#25262C' }}>
                스타일을 초기화하시겠습니까?
              </span>
              <span style={{ fontSize: 14, color: '#8E919B', textAlign: 'center', lineHeight: '22px' }}>
                문서 스타일 설정이 기본값으로 되돌아갑니다.
                <br />
                이 작업은 되돌릴 수 없습니다.
              </span>
            </Flex>
          </Flex>
        </Dialog.Content>
        <Dialog.Footer>
          <Button variant="outlined" width="100%" size="large" onClick={onClose}>
            취소
          </Button>
          <Button
            variant="warning"
            width="100%"
            size="large"
            onClick={() => {
              setTheme(DEFAULT_THEME);
              setEdits({});
              onClose();
            }}
          >
            초기화
          </Button>
        </Dialog.Footer>
      </Dialog>
    ));
  }, [modal]);

  /** 로컬 edits를 theme에 merge하여 최종 테마 반환 */
  const buildMergedTheme = useCallback(() => {
    const mergedTheme = structuredClone(theme);

    for (const [styleKey, edit] of Object.entries(edits)) {
      const hasChar = Object.keys(edit.character).length > 0;
      const hasPara = Object.keys(edit.paragraph).length > 0;
      if (!hasChar && !hasPara) continue;

      const entry = style[styleKey];
      const charKey = entry.character_style ?? '';
      const paraKey = entry.paragraph_style ?? '';

      if (charKey && hasChar) {
        mergedTheme.character[charKey] = {
          ...mergedTheme.character[charKey],
          ...edit.character
        };
      }
      if (paraKey && hasPara) {
        const merged = {
          ...mergedTheme.paragraph[paraKey],
          ...edit.paragraph
        };
        for (const [k, v] of Object.entries(
          merged as Record<string, unknown>
        )) {
          if (v === REMOVE_FIELD) {
            delete (merged as Record<string, unknown>)[k];
          }
        }
        mergedTheme.paragraph[paraKey] = merged;
      }
    }

    return mergedTheme;
  }, [edits, style, theme]);

  // edits 변경 시 부모에 merged theme 전달
  useEffect(() => {
    onThemeChange(buildMergedTheme());
  }, [buildMergedTheme, onThemeChange]);

  const styleKeys = Object.keys(style);
  const safeSelectedKey = style[selectedKey]
    ? selectedKey
    : (styleKeys[0] ?? 'l1');

  if (styleKeys.length === 0) return null;

  const selectedCharStyle =
    character[style[safeSelectedKey].character_style ?? ''];
  const selectedParaStyle =
    paragraph[style[safeSelectedKey].paragraph_style ?? ''];

  const getChar = (field: keyof CharacterStyle) =>
    getCharacterValue(edits, safeSelectedKey, selectedCharStyle, field);
  const getPara = (field: keyof ParagraphStyle) => {
    const val: unknown = getParagraphValue(
      edits,
      safeSelectedKey,
      selectedParaStyle,
      field
    );
    return val === REMOVE_FIELD ? undefined : val;
  };

  const currentSize = (getChar('size') as number) ?? 12;
  const currentBold = (getChar('bold') as boolean) ?? false;
  const currentLineSpacing = (getPara('line_spacing') as number) ?? 160;
  const currentMark = getPara('mark') as { char: string } | null | undefined;
  const currentMarginTop = (getPara('margin_top') as number) ?? 0;
  const currentMarginBottom = (getPara('margin_bottom') as number) ?? 0;
  const currentFace = (getChar('face') as string[]) ?? [];

  return (
    <Flex direction="column" width="100%" style={{ minHeight: '0px', flex: 1 }}>
      <StyledFunnelContentWrapper>
        <StyledStepHeader>
          <StyledTemplateName>&apos;{templateName}&apos;</StyledTemplateName>
          <StyledStepSubtitle>문서 생성 세부 설정</StyledStepSubtitle>
        </StyledStepHeader>

        <StyledInfoBanner>
          <Info size={16} />
          <span>완벽한 사업계획서를 위해 문서의 스타일 옵션을 확인해주세요.</span>
        </StyledInfoBanner>

        <StyledStyleCard>
          <Flex direction="column" gap={4}>
            <StyledCardTitle>문서 스타일</StyledCardTitle>
            <StyledCardDescription>
              문서 전체에 적용되는 스타일을 설정합니다
            </StyledCardDescription>
          </Flex>

          <StyledContentRow>
            <StyledStyleList>
              {styleKeys.map((key) => (
                <StyledStylePill
                  key={key}
                  type="button"
                  $active={key === safeSelectedKey}
                  onClick={() => setSelectedKey(key)}
                >
                  {STYLE_DISPLAY_NAMES[key]}
                </StyledStylePill>
              ))}
            </StyledStyleList>

            <StyledPropertiesPanel>
              <StyledFieldsWrapper>
                <StyledFieldRow>
                  <StyledFieldGroup>
                    <StyledFieldLabel>크기</StyledFieldLabel>
                    <Menu>
                      <MenuTrigger asChild>
                        <StyledMenuTriggerBox type="button">
                          <span>{currentSize}pt</span>
                          <ChevronDown size={16} />
                        </StyledMenuTriggerBox>
                      </MenuTrigger>
                      <MenuContent style={{ minWidth: 'var(--radix-dropdown-menu-trigger-width)' }}>
                        {FONT_SIZES.map((s) => (
                          <MenuItem key={s} onSelect={() => updateCharacter('size', s)}>
                            {s}pt
                          </MenuItem>
                        ))}
                      </MenuContent>
                    </Menu>
                  </StyledFieldGroup>
                  <StyledFieldGroup>
                    <StyledFieldLabel>글꼴</StyledFieldLabel>
                    <Menu>
                      <MenuTrigger asChild>
                        <StyledMenuTriggerBox type="button">
                          <span>{currentFace[0] ?? '맑은 고딕'}</span>
                          <ChevronDown size={16} />
                        </StyledMenuTriggerBox>
                      </MenuTrigger>
                      <MenuContent style={{ minWidth: 'var(--radix-dropdown-menu-trigger-width)', maxHeight: 300, overflowY: 'auto' }}>
                        {currentFace[0] &&
                          ![...fallbackFonts, ...localFonts].includes(currentFace[0]) && (
                            <MenuItem
                              key={currentFace[0]}
                              onSelect={() => updateCharacter('face', [currentFace[0]])}
                            >
                              {currentFace[0]}
                            </MenuItem>
                          )}
                        {fallbackFonts.map((f) => (
                          <MenuItem key={f} onSelect={() => updateCharacter('face', [f])}>
                            {f}
                          </MenuItem>
                        ))}
                        {localFonts.length > 0 && (
                          <>
                            <StyledHorizontalDivider />
                            {localFonts.map((f) => (
                              <MenuItem key={f} onSelect={() => updateCharacter('face', [f])}>
                                {f}
                              </MenuItem>
                            ))}
                          </>
                        )}
                      </MenuContent>
                    </Menu>
                  </StyledFieldGroup>
                </StyledFieldRow>

                <StyledFieldRow>
                  <StyledFieldGroup>
                    <StyledFieldLabel>줄간격</StyledFieldLabel>
                    <Menu>
                      <MenuTrigger asChild>
                        <StyledMenuTriggerBox type="button">
                          <span>{currentLineSpacing}%</span>
                          <ChevronDown size={16} />
                        </StyledMenuTriggerBox>
                      </MenuTrigger>
                      <MenuContent style={{ minWidth: 'var(--radix-dropdown-menu-trigger-width)' }}>
                        {LINE_SPACINGS.map((s) => (
                          <MenuItem key={s} onSelect={() => updateParagraph('line_spacing', s)}>
                            {s}%
                          </MenuItem>
                        ))}
                      </MenuContent>
                    </Menu>
                  </StyledFieldGroup>
                  <StyledFieldGroup>
                    <StyledFieldLabel>글머리 기호</StyledFieldLabel>
                    <Menu>
                      <MenuTrigger asChild>
                        <StyledMenuTriggerBox type="button">
                          <span>{currentMark?.char ?? '없음'}</span>
                          <ChevronDown size={16} />
                        </StyledMenuTriggerBox>
                      </MenuTrigger>
                      <MenuContent style={{ minWidth: 'var(--radix-dropdown-menu-trigger-width)' }}>
                        {MARK_OPTIONS.map((m) => (
                          <MenuItem
                            key={m?.char ?? '__none'}
                            onSelect={() => updateParagraph('mark', m)}
                          >
                            {m?.char ?? '없음'}
                          </MenuItem>
                        ))}
                      </MenuContent>
                    </Menu>
                  </StyledFieldGroup>
                </StyledFieldRow>

                <StyledFieldRow>
                  <StyledFieldGroup>
                    <StyledFieldLabel>문단 위 간격</StyledFieldLabel>
                    <Menu>
                      <MenuTrigger asChild>
                        <StyledMenuTriggerBox type="button">
                          <span>{currentMarginTop}pt</span>
                          <ChevronDown size={16} />
                        </StyledMenuTriggerBox>
                      </MenuTrigger>
                      <MenuContent style={{ minWidth: 'var(--radix-dropdown-menu-trigger-width)' }}>
                        {PARAGRAPH_SPACINGS.map((s) => (
                          <MenuItem key={s} onSelect={() => updateParagraph('margin_top', s)}>
                            {s}pt
                          </MenuItem>
                        ))}
                      </MenuContent>
                    </Menu>
                  </StyledFieldGroup>
                  <StyledFieldGroup>
                    <StyledFieldLabel>문단 아래 간격</StyledFieldLabel>
                    <Menu>
                      <MenuTrigger asChild>
                        <StyledMenuTriggerBox type="button">
                          <span>{currentMarginBottom}pt</span>
                          <ChevronDown size={16} />
                        </StyledMenuTriggerBox>
                      </MenuTrigger>
                      <MenuContent style={{ minWidth: 'var(--radix-dropdown-menu-trigger-width)' }}>
                        {PARAGRAPH_SPACINGS.map((s) => (
                          <MenuItem key={s} onSelect={() => updateParagraph('margin_bottom', s)}>
                            {s}pt
                          </MenuItem>
                        ))}
                      </MenuContent>
                    </Menu>
                  </StyledFieldGroup>
                </StyledFieldRow>
              </StyledFieldsWrapper>

              <div>
                <StyledFieldLabel>서식</StyledFieldLabel>
                <StyledAttrGroup style={{ marginTop: 4, width: 'fit-content' }}>
                  <StyledAttrButton
                    type="button"
                    $active={currentBold}
                    onClick={() => toggleCharBool('bold')}
                    title="굵게"
                  >
                    <strong>B</strong>
                  </StyledAttrButton>
                </StyledAttrGroup>
              </div>

              <StyledHorizontalDivider />

              <div>
                <StyledFieldLabel>미리보기</StyledFieldLabel>
                <StyledPreviewBox style={{ marginTop: 4 }}>
                  {Object.entries(style).map(([key, value]) => {
                    const previewStyle = buildPreviewStyle(
                      edits,
                      key,
                      character[value.character_style ?? ''],
                      paragraph[value.paragraph_style ?? '']
                    );
                    const rawMark: unknown = getParagraphValue(
                      edits,
                      key,
                      paragraph[value.paragraph_style ?? ''],
                      'mark'
                    );
                    const mark =
                      rawMark === REMOVE_FIELD
                        ? undefined
                        : (rawMark as { char: string } | undefined);
                    return (
                      <StyledPreviewLine key={key} $style={previewStyle}>
                        {mark ? `${mark.char} ` : ''}
                        {PREVIEW_TEXTS[key] ?? `${key} 텍스트`}
                      </StyledPreviewLine>
                    );
                  })}
                </StyledPreviewBox>
                <StyledPreviewNotice>
                  <Info size={12} />
                  미리보기는 실제와 다를 수 있으며, 내려받은 파일에는 정상 적용됩니다.
                </StyledPreviewNotice>
              </div>
            </StyledPropertiesPanel>
          </StyledContentRow>

          <Flex justify="flex-end">
            <Button
              type="button"
              variant="outlined"
              size="medium"
              onClick={handleReset}
            >
              기본값 초기화
            </Button>
          </Flex>
        </StyledStyleCard>
      </StyledFunnelContentWrapper>

      <StyledSettingsFooter>
        <Button type="button" variant="outlined" size="large" onClick={onBack}>
          이전
        </Button>
        <Button
          type="button"
          variant="filled"
          size="large"
          onClick={onSubmit}
          style={{ marginLeft: 'auto' }}
        >
          사업계획서 생성
        </Button>
      </StyledSettingsFooter>
    </Flex>
  );
}
